-- Chunk 14: append-only inventory accounting
CREATE TABLE "InventoryProfile" ("id" TEXT NOT NULL,"shopId" TEXT NOT NULL,"enabled" BOOLEAN NOT NULL DEFAULT false,"legacyDualMode" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "InventoryProfile_pkey" PRIMARY KEY("id"));
CREATE TABLE "InventoryLocation" ("id" TEXT NOT NULL,"shopId" TEXT NOT NULL,"name" TEXT NOT NULL,"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "InventoryLocation_pkey" PRIMARY KEY("id"));
CREATE TABLE "StockCategory" ("id" TEXT NOT NULL,"shopId" TEXT NOT NULL,"name" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "StockCategory_pkey" PRIMARY KEY("id"));
CREATE TABLE "StockItem" ("id" TEXT NOT NULL,"shopId" TEXT NOT NULL,"categoryId" TEXT,"sku" TEXT,"name" TEXT NOT NULL,"unit" TEXT NOT NULL DEFAULT 'unit',"weightedAverageCostMinor" INTEGER NOT NULL DEFAULT 0,"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "StockItem_pkey" PRIMARY KEY("id"));
CREATE TABLE "Supplier" ("id" TEXT NOT NULL,"shopId" TEXT NOT NULL,"name" TEXT NOT NULL,"email" TEXT,"phone" TEXT,"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Supplier_pkey" PRIMARY KEY("id"));
CREATE TABLE "Recipe" ("id" TEXT NOT NULL,"shopId" TEXT NOT NULL,"key" TEXT NOT NULL,"name" TEXT NOT NULL,"menuItemId" TEXT,"yieldMilli" INTEGER NOT NULL DEFAULT 1000,"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Recipe_pkey" PRIMARY KEY("id"));
CREATE TABLE "RecipeComponent" ("id" TEXT NOT NULL,"shopId" TEXT NOT NULL,"recipeId" TEXT NOT NULL,"stockItemId" TEXT NOT NULL,"quantityMilli" INTEGER NOT NULL,CONSTRAINT "RecipeComponent_pkey" PRIMARY KEY("id"));
CREATE TABLE "StockMovement" ("id" TEXT NOT NULL,"shopId" TEXT NOT NULL,"stockItemId" TEXT NOT NULL,"locationId" TEXT NOT NULL,"kind" TEXT NOT NULL,"quantityMilli" INTEGER NOT NULL,"unitCostMinor" INTEGER NOT NULL,"totalCostMinor" INTEGER NOT NULL,"referenceType" TEXT,"referenceId" TEXT,"movementKey" TEXT NOT NULL,"note" TEXT,"actorUserId" TEXT NOT NULL,"occurredAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "StockMovement_pkey" PRIMARY KEY("id"));
CREATE TABLE "PurchaseOrder" ("id" TEXT NOT NULL,"shopId" TEXT NOT NULL,"supplierId" TEXT NOT NULL,"locationId" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'DRAFT',"orderedAt" TIMESTAMP(3),"closedAt" TIMESTAMP(3),"createdById" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "PurchaseOrder_pkey" PRIMARY KEY("id"));
CREATE TABLE "PurchaseOrderLine" ("id" TEXT NOT NULL,"shopId" TEXT NOT NULL,"purchaseOrderId" TEXT NOT NULL,"stockItemId" TEXT NOT NULL,"orderedMilli" INTEGER NOT NULL,"unitCostMinor" INTEGER NOT NULL,CONSTRAINT "PurchaseOrderLine_pkey" PRIMARY KEY("id"));
CREATE TABLE "GoodsReceipt" ("id" TEXT NOT NULL,"shopId" TEXT NOT NULL,"purchaseOrderId" TEXT,"supplierId" TEXT,"locationId" TEXT NOT NULL,"receivedById" TEXT NOT NULL,"receivedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "GoodsReceipt_pkey" PRIMARY KEY("id"));
CREATE TABLE "GoodsReceiptLine" ("id" TEXT NOT NULL,"shopId" TEXT NOT NULL,"goodsReceiptId" TEXT NOT NULL,"stockItemId" TEXT NOT NULL,"quantityMilli" INTEGER NOT NULL,"unitCostMinor" INTEGER NOT NULL,CONSTRAINT "GoodsReceiptLine_pkey" PRIMARY KEY("id"));
CREATE TABLE "Stocktake" ("id" TEXT NOT NULL,"shopId" TEXT NOT NULL,"locationId" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'OPEN',"countedById" TEXT NOT NULL,"postedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "Stocktake_pkey" PRIMARY KEY("id"));
CREATE TABLE "StocktakeLine" ("id" TEXT NOT NULL,"shopId" TEXT NOT NULL,"stocktakeId" TEXT NOT NULL,"stockItemId" TEXT NOT NULL,"countedMilli" INTEGER NOT NULL,"expectedMilli" INTEGER NOT NULL,"adjustmentMilli" INTEGER NOT NULL,CONSTRAINT "StocktakeLine_pkey" PRIMARY KEY("id"));
CREATE TABLE "StockTransfer" ("id" TEXT NOT NULL,"shopId" TEXT NOT NULL,"stockItemId" TEXT NOT NULL,"fromLocationId" TEXT NOT NULL,"toLocationId" TEXT NOT NULL,"quantityMilli" INTEGER NOT NULL,"actorUserId" TEXT NOT NULL,"transferredAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "StockTransfer_pkey" PRIMARY KEY("id"));
CREATE UNIQUE INDEX "InventoryProfile_shopId_key" ON "InventoryProfile"("shopId");
CREATE UNIQUE INDEX "InventoryLocation_shopId_name_key" ON "InventoryLocation"("shopId","name"); CREATE INDEX "InventoryLocation_shopId_active_idx" ON "InventoryLocation"("shopId","active");
CREATE UNIQUE INDEX "StockCategory_shopId_name_key" ON "StockCategory"("shopId","name");
CREATE UNIQUE INDEX "StockItem_shopId_sku_key" ON "StockItem"("shopId","sku"); CREATE INDEX "StockItem_shopId_active_name_idx" ON "StockItem"("shopId","active","name");
CREATE INDEX "Supplier_shopId_active_name_idx" ON "Supplier"("shopId","active","name");
CREATE UNIQUE INDEX "Recipe_shopId_key_key" ON "Recipe"("shopId","key"); CREATE INDEX "Recipe_shopId_menuItemId_active_idx" ON "Recipe"("shopId","menuItemId","active");
CREATE UNIQUE INDEX "RecipeComponent_shopId_recipeId_stockItemId_key" ON "RecipeComponent"("shopId","recipeId","stockItemId"); CREATE INDEX "RecipeComponent_shopId_stockItemId_idx" ON "RecipeComponent"("shopId","stockItemId");
CREATE UNIQUE INDEX "StockMovement_movementKey_key" ON "StockMovement"("movementKey"); CREATE INDEX "StockMovement_shopId_stockItemId_locationId_occurredAt_idx" ON "StockMovement"("shopId","stockItemId","locationId","occurredAt"); CREATE INDEX "StockMovement_shopId_kind_occurredAt_idx" ON "StockMovement"("shopId","kind","occurredAt"); CREATE INDEX "StockMovement_shopId_referenceType_referenceId_idx" ON "StockMovement"("shopId","referenceType","referenceId");
CREATE INDEX "PurchaseOrder_shopId_status_createdAt_idx" ON "PurchaseOrder"("shopId","status","createdAt"); CREATE INDEX "PurchaseOrderLine_shopId_purchaseOrderId_idx" ON "PurchaseOrderLine"("shopId","purchaseOrderId");
CREATE INDEX "GoodsReceipt_shopId_purchaseOrderId_receivedAt_idx" ON "GoodsReceipt"("shopId","purchaseOrderId","receivedAt"); CREATE INDEX "GoodsReceiptLine_shopId_goodsReceiptId_idx" ON "GoodsReceiptLine"("shopId","goodsReceiptId");
CREATE INDEX "Stocktake_shopId_locationId_status_createdAt_idx" ON "Stocktake"("shopId","locationId","status","createdAt"); CREATE UNIQUE INDEX "StocktakeLine_shopId_stocktakeId_stockItemId_key" ON "StocktakeLine"("shopId","stocktakeId","stockItemId"); CREATE INDEX "StockTransfer_shopId_stockItemId_transferredAt_idx" ON "StockTransfer"("shopId","stockItemId","transferredAt");
